interface UserPreferences {
  theme: string;
  notifications: boolean;
  language: string;
  lastLogin: string;
}

async function getUserPreferences(): Promise<UserPreferences> {
  const baseUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3000';
  const res = await fetch(`${baseUrl}/api/user/preferences`, {
    cache: 'no-store',
  });

  if (!res.ok) {
    throw new Error('Failed to fetch user preferences');
  }

  return res.json();
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences();

  return (
    <div className="p-4 border rounded-lg shadow-sm">
      <h2 className="text-xl font-bold mb-4">User Dashboard</h2>
      <div className="space-y-2">
        <p><strong>Theme:</strong> {preferences.theme}</p>
        <p><strong>Language:</strong> {preferences.language}</p>
        <p><strong>Notifications:</strong> {preferences.notifications ? 'Enabled' : 'Disabled'}</p>
        <p><strong>Last Login:</strong> {new Date(preferences.lastLogin).toLocaleString()}</p>
      </div>
    </div>
  );
}

